ee:message.ee:set-payload:
%dw 2.0
output application/json

var actionFeatures = [
    "flujo",
    "origen_equipo",
    "PERFIL",
    "score",
    "AutorizoUsoMismaFirma"
]

fun colombiaDate() =
    (now() >> "America/Bogota")

fun orderCreationDate() =
    colombiaDate() as String {format: "yyyy/MM/dd HH:mm:ss"}

fun atdpDate() =
    (colombiaDate() as LocalDateTime)
        as String {format: "yyyy-MM-dd'T'HH:mm:ss"}

---
{
    requestHeader: {
        system: {
            correlationId: vars.correlationId default ""
        }
    },
    requestBody: {
        documentType: payload.requestCustomer.documentType,
        identificationNumber: payload.requestCustomer.documentNumber,
        orderType: payload.through.throughType,
        orderSubtype: payload.through.throughSubtype,
        orderStatus: "PENDIENTE",
        orderCreationDate: orderCreationDate(),
        creatorUser: payload.createdBy,
        modifierUser: payload.updatedBy,
        sellerUser: payload.createdBy,
        channel: payload.channel,
        subchannel: payload.subcategory,
        sourceSystem: "MDM-MOV",
        catalogGroupingNumber: payload.requestService.productGroupingNumber as String,
        invoiceDeliveryType: payload.requestBillingAccount.deliveryType,
        planType: payload.requestService.planType,

        orderCharacteristics:
            payload.featureOrder map (item) ->
                (
                    {
                        characteristic: item.feature,
                        value: item.value as String
                    }
                    ++
                    (
                        if (actionFeatures contains item.feature)
                            {
                                action: item.feature
                            }
                        else
                            {}
                    )
                    ++
                    {
                        extractorUpdate: "1"
                    }
                ),

        setType: payload.setType,

        atdp: {
            date: atdpDate()
        }
    }
}

%dw 2.0 output application/json
var payloadRequest = vars.reqIn
fun colombiaDate(format) = (now() >> "America/Bogota") as String {format: format}
--- { pqrType: "VTA", pqrDate: colombiaDate("dd/MM/yyyy HH:mm:ss"), system: payloadRequest.channel, orderNumber: vars.responseOrderIni.body.databaseId, connectionNumber: "", identification: payloadRequest.requestCustomer.documentNumber, identificationType: payloadRequest.requestCustomer.documentType, user: payloadRequest.channel }

%dw 2.0
output application/json

var cun = payload.cun

---
{
	requestHeader: {
		system: {
			name: vars.reqIn.channel
		}
	},
	requestBody: {
		id: vars.responseOrderIni.body.mongoId,
		cun: cun.cunNumber,
		documentType: vars.reqIn.requestCustomer.documentType,
		identificationNumber: vars.reqIn.requestCustomer.documentNumber,
		orderNumber: vars.responseOrderIni.body.databaseId,
		"setType": "U"
	}
}

%dw 2.0
output application/json

---
{
    requestHeader: {
        system: {
            correlationId: vars.correlationId default ""
        }
    },
    requestBody: {
        orderNumber: vars.responseOrderIni.body.databaseId,
        phase: "ORDEN CREADA",
        updateUser: vars.reqIn.createdBy,
        status: "EXITOSO"
    }
}

%dw 2.0
output application/json

---
{
  id: vars.responseOrderIni.body.mongoId,
  orderDetail: {
    productType: "Plan",
    productCode: "1807",
    product: "TELEFONIA MOVIL (LTE)",
    planOffer: "PLAN SUPERSONICA PRO PREPAGO",
    offerValue: "0",
    serviceClass: "LTE PREPAID",
    action: "ADD",
    serviceMode: "PREPAGO",
    serviceCharacteristics: [
      {
        characteristic: "RVC PARM Index DS",
        value: "NA"
      },
      {
        characteristic: "Price",
        value: "0"
      },
      {
        characteristic: "NOMBRE PLAN",
        value: (payload.result filter ($.tipo_producto == "Primario"))[0].producto default ""
      },
      {
        characteristic: "RVC FEAT",
        value: "NA"
      },
      {
        characteristic: "Service_Class",
        value: "LTE PREPAGO"
      },
      {
        characteristic: "Modalidad_Servicio",
        value: "PREPAGO"
      },
      {
        characteristic: "MODO ADQUISICION EQUIPO",
        value: "PROPIO"
      }
    ]
  },
  setType: "U"
}

%dw 2.0
output application/json

var items = vars.payloadResponseCMP_OF_PROD.result default []

var bundles = items filter ((item) -> item.tipo_producto == "BUNDLE")
var primarios = items filter ((item) -> item.tipo_producto == "Primario")
var secundarios = items filter ((item) -> item.tipo_producto == "SECUNDARIO")

fun getId(item) =
    item.'_id'.'\$oid' default item.'_id' default ""

---
{
  requestHeader: {
    system: {
      name: "PORTAL_LTE",
      correlationId: vars.correlationId default "",
      processingServer: "APP_SERVER"
    }
  },
  requestBody: {
    orderNumber: "MDM-MOV-337153",
    bundles: bundles map (bundle) -> {
      id: getId(bundle),
      catalogId: bundle.id_producto default "",
      name: bundle.producto default "",
      activationDate: true,
      deactivationDate: true,
      primaryItems: primarios map (primary) -> {
        id: getId(primary),
        primaryId: primary.id_producto default "",
        name: primary.producto default "",
        activationDate: null,
        deactivationDate: null,
        secondaryItems: secundarios map (secondary) -> {
          id: getId(secondary),
          secondaryId: secondary.id_producto default "",
          name: secondary.producto default "",
          activationDate: true,
          deactivationDate: true
        }
      },
      optionalItems: []
    }
  }
}

%dw 2.0
output application/json

---
{
    requestHeader: {
        system: {
            correlationId: vars.correlationId default ""
        }
    },
    requestBody: {
        orderNumber: vars.responseOrderIni.body.mongoId,
        phase: "ORDEN CREADA",
        updateUser: vars.reqIn.createdBy,
        status: "CLIENTE CARGADO"
    }
}

%dw 2.0 output application/json
var orderId = vars.responseOrderIni.body.databaseId default ""
--- { channel: "PORTAL MOVILIDAD", iccid: payload.iccid, externalId: orderId, orderId: orderId, serviceId: orderId ++ "-1", operation: "RESERVAR", resourceType: "ICCID", procedure: "VENTA" }

%dw 2.0
output application/json

var orderId = vars.responseOrderIni.body.databaseId default ""

---
{
  query: {
    update: "MDM_ORDEN",
    updates: [
      {
        q: {
          Numero_Orden: orderId
        },
        u: {
          "\$push": {
            Caracteristicas_Orden: {
              "\$each": [
                {
                  Caracteristica: "iccid",
                  Valor: payload.iccid,
                  Accion: "iccid",
                  actualizacion_extractor: "1"
                },
                {
                  Caracteristica: "msisdn",
                  Valor: payload.msisdn,
                  Accion: "msisdn",
                  actualizacion_extractor: "1"
                }
              ]
            }
          }
        },
        multi: false
      }
    ]
  }
}

%dw 2.0
output application/json

---
{
    requestHeader: {
        system: {
            correlationId: vars.correlationId default ""
        }
    },
    requestBody: {
        orderNumber: vars.responseOrderIni.body.databaseId,
        phase: "INVENTARIO",
        updateUser: vars.reqIn.createdBy,
        status: "EXITOSO"
    }
}

%dw 2.0
output application/json

var orderId = vars.responseOrderIni.body.databaseId default ""

fun colombiaDateTime() =
    (now() >> "America/Bogota") as String {
        format: "yyyy-MM-dd'T'HH:mm:ss'Z'"
    }

---
{
  query: {
    update: "MDM_ACTIVACION_ESIM",
    updates: [
      {
        q: {
          Numero_Orden: orderId
        },
        u: {
          "\$set": {
            Estado: "RESERVADO",
            Usuario_Modificacion: vars.reqIn.updatedBy,
            Fecha_Modificacion: {
              "\$date": colombiaDateTime()
            }
          }
        },
        multi: false
      }
    ]
  }
}

%dw 2.0
output application/json

var orderNumber = vars.responseOrderIni.body.databaseId
var user = vars.reqIn.createdBy

---
{
  requestHeader: {
    externalId: "Orquestador_Fija",
    system: "Orquestador_Fija"
  },
  requestBody: {
    id: "PortalLTE_Activacion_Linea",
    parameters: [
      {
        attribute: "ORDER_NUM",
        value: orderNumber
      },
      {
        attribute: "USERID",
        value: user
      }
    ]
  }
}

%dw 2.0
output application/json

